	-- BACK UP faculty_workload first. Preserves admins and official_timetable_rows.
USE faculty_workload;
SET SQL_SAFE_UPDATES = 0;
SET FOREIGN_KEY_CHECKS=0;
DELETE h FROM allocation_history h JOIN subjects x ON x.id=h.subject_id WHERE x.subject_code IN ('MCA101','MCA302','CSE505');
DELETE FROM timetable_slots WHERE subject_id IN (SELECT id FROM subjects WHERE subject_code IN ('MCA101','MCA302','CSE505')) OR faculty_id IN (SELECT id FROM faculty WHERE faculty_code IN ('FAC-101','FAC-102','FAC-103'));
DELETE FROM allocations WHERE subject_id IN (SELECT id FROM subjects WHERE subject_code IN ('MCA101','MCA302','CSE505')) OR faculty_id IN (SELECT id FROM faculty WHERE faculty_code IN ('FAC-101','FAC-102','FAC-103'));
DELETE FROM subject_slots WHERE subject_id IN (SELECT id FROM subjects WHERE subject_code IN ('MCA101','MCA302','CSE505'));
DELETE FROM faculty_availability WHERE faculty_id IN (SELECT id FROM faculty WHERE faculty_code IN ('FAC-101','FAC-102','FAC-103'));
DELETE FROM subjects WHERE subject_code IN ('MCA101','MCA302','CSE505');
DELETE FROM faculty WHERE faculty_code IN ('FAC-101','FAC-102','FAC-103');
ALTER TABLE classes MODIFY semester TINYINT UNSIGNED NULL;
ALTER TABLE classes DROP CHECK chk_class_semester;
ALTER TABLE classes ADD CONSTRAINT chk_class_semester CHECK (semester IS NULL OR semester BETWEEN 1 AND 8);
SET FOREIGN_KEY_CHECKS=1;
